        -- RV32Zmmul
        "0000001----------000-----0110011", -- mul
        "0000001----------001-----0110011", -- mulh
        "0000001----------010-----0110011", -- mulhsu
        "0000001----------011-----0110011", -- mulhu
        -- Custom extensions
        "-------------------------0001011", -- in
        "-------------------------0101011", -- out
        "--------------------------------"  -- illegal instruction
    );
    constant addrs: OpcodeTable(patterns'range) := (
        "100000000000", -- lui
        "100000000001", -- auipc
        "100000000101", -- jal
