    pure function immediate_decoder(id: natural; d_in: std_ulogic_vector) return std_ulogic_vector;
end package;

package body firmware is
    pure function immediate_decoder(id: natural; d_in: std_ulogic_vector)
    return std_ulogic_vector is
    begin
        case id is
            when 1 => return (d_in'high - 12 downto 0 => d_in(31)) & d_in(31 downto 20);
            when 2 => return (d_in'high - 12 downto 0 => d_in(31)) & d_in(31 downto 25) & d_in(11 downto 7);
            when 3 => return (d_in'high - 13 downto 0 => d_in(31)) & d_in(31 downto 31) & d_in(7 downto 7) & d_in(30 downto 25) & d_in(11 downto 8) & "0";
            when 4 => return d_in(31 downto 12) & "000000000000";
            when 5 => return (d_in'high - 21 downto 0 => d_in(31)) & d_in(31 downto 31) & d_in(19 downto 12) & d_in(20 downto 20) & d_in(30 downto 21) & "0";
            when others => return d_in;
        end case;
    end;
end package body;
